@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable

<select class="form-select form-select-sm" value="@Warehouse.SelectedWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 200px;">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        Warehouse.SetWarehouse(e.Value?.ToString() ?? "");
    }

    public void Dispose() => Warehouse.OnChange -= _handler;
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge bg-danger rounded-pill ms-2">@AlertService.LowStockCount</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
        AlertService.StopPolling();
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @Warehouse.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@Warehouse.SelectedWarehouseName (@Warehouse.SelectedWarehouseId)</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LowStockCount > 0)
            {
                <span class="text-danger fs-4">
                    ⚠️ @AlertService.LowStockCount items below minimum stock level
                </span>
            }
            else
            {
                <span class="text-success fs-4">✅ All items at or above minimum levels</span>
            }
        </p>
        <small class="text-muted">Auto-refreshes every 10 seconds</small>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        Warehouse.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        AlertService.StopPolling();
    }
}

